        _log_tool_round_limit(request=provider_request, state=next_tool_state)
        return _ResultStep(
            state=state,
            response=build_public_response(
                result,
                output_text="",
                tool_calls=result.tool_calls,
                tool_trace=next_tool_state.steps,
